import os,shutil,subprocess
from pathlib import Path
targets=[Path('/root/.gradle/caches/9.6.0'),Path('/root/.gradle/caches/build-cache-1')]
protected=['pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa','pm2-root','nginx','postgresql@16-main','ssh']
def active(x):
 return subprocess.run(['systemctl','is-active',x+'.service'],capture_output=True,text=True,timeout=8).stdout.strip()
def pm2():
 import json
 r=subprocess.run(['pm2','jlist'],capture_output=True,text=True,timeout=12)
 if r.returncode:raise RuntimeError('PM2 unavailable')
 return {x.get('name'):(x.get('pm2_env') or {}).get('status') for x in json.loads(r.stdout)}
def diskuse(p):
 r=subprocess.run(['du','-x','-s','-B1',str(p)],capture_output=True,text=True,timeout=40)
 if r.returncode:raise RuntimeError('Failed to measure '+str(p))
 return int(r.stdout.split()[0])
baseline={s:active(s) for s in protected}
if any(v!='active' for v in baseline.values()):raise RuntimeError('Protected service not active pre-clean')
baseline_bots=pm2()
for n in ('iptvpn_bot','telegram-robot-leads'):
 if baseline_bots.get(n)!='online':raise RuntimeError('Bot offline pre-clean')
for proc in Path('/proc').iterdir():
 if not proc.name.isdigit():continue
 try:
  raw=(proc/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='replace')
  if 'python3 -' in raw:continue
  if any(x in raw for x in ('org.gradle.launcher.daemon','GradleDaemon','GradleWorkerMain','gradlew','GradleWrapperMain','kotlinc')):
   raise RuntimeError('Gradle process running: '+proc.name)
 except OSError:pass
cache=Path('/root/.gradle/caches')
if cache.is_symlink() or not cache.is_dir():raise RuntimeError('Unexpected Gradle cache parent')
preserve=[cache/'modules-2',Path('/root/.gradle/wrapper')]
if any(not q.is_dir() for q in preserve):raise RuntimeError('Critical Gradle dependencies absent pre-clean')
bytes_removed=0
before=shutil.disk_usage('/').free
for path in targets:
 if not path.is_dir() or path.is_symlink() or path.parent!=cache or path.stat().st_uid!=0:
  raise RuntimeError('Target not a verified root-owned cache')
 sz=diskuse(path)
 bytes_removed+=sz
 print('REGENERABLE_CACHE='+str(path)+'|BYTES='+str(sz))
for path in targets:
 shutil.rmtree(path)
for path in targets:
 if path.exists() or path.is_symlink():raise RuntimeError('Cached files remain')
if any(not q.is_dir() for q in preserve):raise RuntimeError('Preserved Gradle download cache or wrapper missing')
after=shutil.disk_usage('/').free
print('GRADLE_REGENERABLE_BYTES_REMOVED='+str(bytes_removed))
print('FREE_DISK_GAIN_BYTES='+str(after-before))
print('OFFLINE_ARTIFACT_CACHE_PRESERVED='+str(preserve[0]))
print('GRADLE_WRAPPER_PRESERVED='+str(preserve[1]))
for name in protected:
 s=active(name)
 print('SERVICE|'+name+'|'+s)
 if s!=baseline[name]:raise RuntimeError('Service changed: '+name)
post=pm2()
for name in ('iptvpn_bot','telegram-robot-leads'):
 print('BOT|'+name+'|'+str(post.get(name)))
 if post.get(name)!='online':raise RuntimeError('Bot offline after cache clean')
print('GRADLE_CACHE_CLEANUP=PASS')
PY
